{
  "scores": [
    {
      "criterion": "stakes",
      "value": 3,
      "ref": "card:limits",
      "reason": "Choices need synthesis, dielectric, stability; outcomes change them only through unchecked simulation-to-reality and one force field."
    },
    {
      "criterion": "lever",
      "value": 5,
      "ref": "plan:predictions.noise_rule",
      "reason": "Noise rules and explicit thresholds separate reorder from confirmation; candidate axis and fixed protocol support the comparison."
    },
    {
      "criterion": "verifiable",
      "value": 5,
      "ref": "card:anchor",
      "reason": "Anchor reproduces published measured ester viscosity and conductivity within stated tolerance; later scores use independent measured values."
    },
    {
      "criterion": "open",
      "value": 5,
      "ref": "card:closest_prior",
      "reason": "Prior only Green-Kubo verifies eight molecules; plan explicitly states the 100–1000 ester shortlist remains open."
    },
    {
      "criterion": "reshape",
      "value": 2,
      "ref": "card:method",
      "reason": "It only parallelizes trajectory replicas and candidate batches within each tier; tiered ranking remains sequential."
    },
    {
      "criterion": "baseline",
      "value": 3,
      "ref": "plan:arms",
      "reason": "Plan times sequential and replica MD arms, but not the machine-learning ranking arm, so baseline timing is incomplete."
    }
  ],
  "decides_by": "verify_300",
  "decides_by_reason": "Decision rule needs MD-versus-ML Spearman and figure climb at 300 candidates, first available after verify_300."
}
